test:
bad_calls = [
    lambda: simulate_basic([]),
    lambda: simulate_basic([[1], [1, 0]]),
    lambda: simulate_basic([[2]]),
    lambda: simulate_basic([[1]], infection_threshold=0),
    lambda: simulate_basic([[1]], infection_threshold=True),
]
for call in bad_calls:
    try:
        call()
        assert False, 'expected ValueError'
    except ValueError:
        pass
